`timescale 1ns/1ps
// Auto-generated by fpga_toolbox.emitters.bridge (protocol=axi4->axi4)
// Joint AXI4-to-AXI4 bridge TB: TB drives the upstream slave port as master and
// models an AXI4 slave on the downstream master port.
module tb_axi4_ooo_reorder_fabric_bridge;
  // DUT 可能有 TB 不关心的额外端口（调试/测试/scan），
  // 显式连接覆盖不到会触发 PINMISSING，故显式关闭。
  /* verilator lint_off PINMISSING */
  logic aclk = 0, aresetn = 0;
  int   errs = 0;
  int   dn_writes = 0;
  int   up_bs = 0;
  logic [31:0] up_wdata = 0;
  logic [31:0] dn_wdata = 0;
  logic [31:0] dn_mem [0:15];

  logic [3:0] s_axi_awid = 0; logic [15:0] s_axi_awaddr = 0;
  logic [7:0] s_axi_awlen = 0; logic [2:0] s_axi_awsize = 0;
  logic [1:0] s_axi_awburst = 0; logic s_axi_awvalid = 0;
  logic s_axi_awready;
  logic [31:0] s_axi_wdata = 0; logic [3:0] s_axi_wstrb = 0;
  logic s_axi_wlast = 0; logic s_axi_wvalid = 0;
  logic s_axi_wready; logic [3:0] s_axi_bid;
  logic [1:0] s_axi_bresp; logic s_axi_bvalid; logic s_axi_bready = 1;
  logic [3:0] s_axi_arid = 0; logic [15:0] s_axi_araddr = 0;
  logic [7:0] s_axi_arlen = 0; logic [2:0] s_axi_arsize = 0;
  logic [1:0] s_axi_arburst = 0; logic s_axi_arvalid = 0;
  logic s_axi_arready;
  logic [3:0] s_axi_rid; logic [31:0] s_axi_rdata;
  logic [1:0] s_axi_rresp; logic s_axi_rlast; logic s_axi_rvalid;
  logic s_axi_rready = 1;
  logic m_axi_awvalid; logic m_axi_awready = 1;
  logic [3:0] m_axi_awid; logic [15:0] m_axi_awaddr;
  logic [7:0] m_axi_awlen;
  logic [2:0] m_axi_awsize = 0;
  logic [1:0] m_axi_awburst = 0;
  logic [2:0] m_axi_arsize = 0;
  logic [1:0] m_axi_arburst = 0;
  logic m_axi_wvalid; logic m_axi_wready = 1;
  logic [31:0] m_axi_wdata; logic [3:0] m_axi_wstrb;
  logic m_axi_wlast;
  logic [3:0] m_axi_bid = 0; logic [1:0] m_axi_bresp = 0;
  logic m_axi_bvalid = 0; logic m_axi_bready;
  logic m_axi_arvalid; logic m_axi_arready = 1;
  logic [3:0] m_axi_arid; logic [15:0] m_axi_araddr;
  logic [7:0] m_axi_arlen;
  logic [31:0] m_axi_rdata = 0; logic m_axi_rvalid = 0;
  logic [1:0] m_axi_rresp = 0;
  logic m_axi_rready; logic m_axi_rlast = 0;
  logic [3:0] m_axi_rid = 0;

  axi4_ooo_reorder_fabric dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axi_awid(s_axi_awid),
    .s_axi_awaddr(s_axi_awaddr),
    .s_axi_awlen(s_axi_awlen),
    .s_axi_awsize(s_axi_awsize),
    .s_axi_awburst(s_axi_awburst),
    .s_axi_awvalid(s_axi_awvalid),
    .s_axi_awready(s_axi_awready),
    .s_axi_wdata(s_axi_wdata),
    .s_axi_wstrb(s_axi_wstrb),
    .s_axi_wlast(s_axi_wlast),
    .s_axi_wvalid(s_axi_wvalid),
    .s_axi_wready(s_axi_wready),
    .s_axi_bid(s_axi_bid),
    .s_axi_bresp(s_axi_bresp),
    .s_axi_bvalid(s_axi_bvalid),
    .s_axi_bready(s_axi_bready),
    .s_axi_arid(s_axi_arid),
    .s_axi_araddr(s_axi_araddr),
    .s_axi_arlen(s_axi_arlen),
    .s_axi_arsize(s_axi_arsize),
    .s_axi_arburst(s_axi_arburst),
    .s_axi_arvalid(s_axi_arvalid),
    .s_axi_arready(s_axi_arready),
    .s_axi_rid(s_axi_rid),
    .s_axi_rdata(s_axi_rdata),
    .s_axi_rresp(s_axi_rresp),
    .s_axi_rlast(s_axi_rlast),
    .s_axi_rvalid(s_axi_rvalid),
    .s_axi_rready(s_axi_rready),
    .m_axi_awid(m_axi_awid),
    .m_axi_awaddr(m_axi_awaddr),
    .m_axi_awlen(m_axi_awlen),
    .m_axi_awsize(m_axi_awsize),
    .m_axi_awburst(m_axi_awburst),
    .m_axi_awvalid(m_axi_awvalid),
    .m_axi_awready(m_axi_awready),
    .m_axi_wdata(m_axi_wdata),
    .m_axi_wstrb(m_axi_wstrb),
    .m_axi_wlast(m_axi_wlast),
    .m_axi_wvalid(m_axi_wvalid),
    .m_axi_wready(m_axi_wready),
    .m_axi_bid(m_axi_bid),
    .m_axi_bresp(m_axi_bresp),
    .m_axi_bvalid(m_axi_bvalid),
    .m_axi_bready(m_axi_bready),
    .m_axi_arid(m_axi_arid),
    .m_axi_araddr(m_axi_araddr),
    .m_axi_arlen(m_axi_arlen),
    .m_axi_arsize(m_axi_arsize),
    .m_axi_arburst(m_axi_arburst),
    .m_axi_arvalid(m_axi_arvalid),
    .m_axi_arready(m_axi_arready),
    .m_axi_rid(m_axi_rid),
    .m_axi_rdata(m_axi_rdata),
    .m_axi_rresp(m_axi_rresp),
    .m_axi_rlast(m_axi_rlast),
    .m_axi_rvalid(m_axi_rvalid),
    .m_axi_rready(m_axi_rready)
  );
  always #5 aclk = ~aclk;

  // ---- 下游 AXI4 从机模型（恒 ready，重点观测数据路径）----
  always @(posedge aclk) begin
    if (aresetn) begin
      m_axi_bvalid <= 0;
      m_axi_rvalid <= 0;
      if (m_axi_awvalid === 1'b1) begin
        m_axi_bid <= m_axi_awid;
      end
      if (m_axi_wvalid === 1'b1) begin
        dn_writes++;
        dn_wdata = m_axi_wdata;
        dn_mem[m_axi_awaddr[3:0]] = m_axi_wdata;
        $display("[CHECK] id=B2W | proto=axi4->axi4 | cat=downstream_write | addr=0x%04h data=0x%08h | status=PASS",
                 m_axi_awaddr, m_axi_wdata);
        if (m_axi_wlast) m_axi_bvalid <= 1;
      end
      if (m_axi_bvalid && m_axi_bready) begin
        m_axi_bvalid <= 0;
      end
      if (m_axi_arvalid === 1'b1) begin
        m_axi_rdata <= dn_mem[m_axi_araddr[3:0]];
        m_axi_rid <= m_axi_arid;
        m_axi_rlast <= 1;
        m_axi_rvalid <= 1;
      end
      if (m_axi_rvalid && m_axi_rready) begin
        m_axi_rvalid <= 0;
      end
    end
  end

  // ---- 上游写：单拍（awlen=0），便于断言地址/数据原样透传 ----
  task automatic axi4_write(input logic [15:0] addr, input logic [31:0] data);
    @(posedge aclk); #1;
    s_axi_awid = 4'd1; s_axi_awaddr = addr;
    s_axi_awlen = 8'd0; s_axi_awsize = 3'd3;
    s_axi_awburst = 2'b01; s_axi_awvalid = 1;
    up_wdata = data;
    while (!s_axi_awready) begin @(posedge aclk); #1; end
    @(posedge aclk); #1;
    s_axi_awvalid = 0;
    s_axi_wdata = data; s_axi_wstrb = '1; s_axi_wlast = 1; s_axi_wvalid = 1;
    while (!s_axi_wready) begin @(posedge aclk); #1; end
    @(posedge aclk); #1;
    s_axi_wvalid = 0; s_axi_wlast = 0;
    // R3：等响应必须同时查 VALID 与 READY —— 只等 bvalid 会被 lint_tb 判 R3，
    // 且真实硬件里若从机 bvalid 恒高而 master 未置 bready，事务也不会完成。
    while (!(s_axi_bvalid && m_axi_bready)) begin @(posedge aclk); #1; end
    up_bs++;
    @(posedge aclk); #1;
  endtask

  initial begin
    // ---- waveform dump (optional; enable with +WAVE on the sim command line) ----
    if ($test$plusargs("WAVE")) begin
      if ($value$plusargs("WAVE_FILE=%s", wave_path)) begin
        $dumpfile(wave_path);
      end else begin
        $dumpfile("wave.vcd");
      end
      $dumpvars(0, tb_axi4_ooo_reorder_fabric_bridge);
    end
    repeat (3) @(posedge aclk);
    aresetn = 1;
    repeat (2) @(posedge aclk);

    axi4_write(16'h0020, 32'hc0ffee00);
    repeat (20) @(posedge aclk);

    if (dn_writes == 0) begin
      $display("[CHECK] id=B2W_NONE | proto=axi4->axi4 | cat=downstream_write | exp=>0 | got=0 | status=FAIL");
      errs++;
    end else begin
      $display("[CHECK] id=B2W_NONE | proto=axi4->axi4 | cat=downstream_write | exp=>0 | got=%0d | status=PASS", dn_writes);
    if (dn_wdata !== up_wdata) begin
      $display("[CHECK] id=B2W_DATA | proto=axi4->axi4 | cat=write_data_passthrough | exp=0x%08h | got=0x%08h | status=FAIL",
               up_wdata, dn_wdata);
      errs++;
    end else begin
      $display("[CHECK] id=B2W_DATA | proto=axi4->axi4 | cat=write_data_passthrough | exp=0x%08h | got=0x%08h | status=PASS",
               up_wdata, dn_wdata);
    end
    end

    if (up_bs == 0) begin
      $display("[CHECK] id=B2B | proto=axi4->axi4 | cat=response_path | exp=bvalid | got=none | status=FAIL");
      errs++;
    end else begin
      $display("[CHECK] id=B2B | proto=axi4->axi4 | cat=response_path | exp=bvalid | got=%0d | status=PASS", up_bs);
    end

    if (errs == 0) begin
      $display("PASS: bridge axi4->axi4 upstream write reaches %0d downstream port(s) with data intact", dn_writes);
      $finish;
    end else begin
      $display("FAIL: bridge axi4->axi4 %0d errors", errs);
      $fatal(1);
    end
  end

  initial begin
    #2000000;
    $display("FAIL: bridge axi4->axi4 timeout (handshake deadlock)");
    $fatal(1);
  end
  string wave_path;
endmodule
